// ── GITHUB SYNC ──
const GH_OWNER='EnoLackner',GH_REPO='ledger-data',GH_FILE='ledger.csv';
const GH_API='https://api.github.com/repos/'+GH_OWNER+'/'+GH_REPO+'/contents/'+GH_FILE;
function getToken(){return localStorage.getItem('gh_token')||'';}
function saveToken(){
  var t=document.getElementById('gh-token-inp').value.trim();
  if(!t){showToast('Enter a token first');return;}
  localStorage.setItem('gh_token',t);
  document.getElementById('gh-token-inp').value='';
  var el=document.getElementById('gh-token-status');if(el)el.textContent='Token saved. Testing…';
  ghTestToken();
}
async function ghTestToken(){
  var tok=getToken();if(!tok)return;
  try{
    var r=await fetch('https://api.github.com/repos/'+GH_OWNER+'/'+GH_REPO,{headers:{'Authorization':'Bearer '+tok,'Accept':'application/vnd.github+json'}});
    var el=document.getElementById('gh-token-status');if(el)el.textContent=r.ok?'Connected to EnoLackner/ledger-data':'Error '+r.status+' — check token';
    setSyncStatus(r.ok?'ok':'err',r.ok?'connected':'auth error');
  }catch(e){setSyncStatus('err','offline');}
}
function setSyncStatus(state,msg){
  var cols={ok:'#4fc3a1',err:'#ef5350',syncing:'#f9a825',idle:'#777'};
  ['sync-status','sync-status-mob'].forEach(function(id){var el=document.getElementById(id);if(el){el.innerHTML='&#9679; '+msg;el.style.color=cols[state]||'#777';}});
}
function stateToCSV(){
  var rows=S.transactions.map(function(t){
    return t.date+',"'+t.description.replace(/"/g,'""')+'",'+t.amount+','+t.category+','+t.month+','+(t.entity||'main');
  });
  return 'date,description,amount,category,month,entity\n'
    +rows.join('\n')
    +'\n#BUDGETS:'+JSON.stringify(S.budgets)
    +'\n#CATS:'+JSON.stringify(CATS)
    +'\n#ENTITIES:'+JSON.stringify(ENTITIES);
}
function csvToState(csv){
  var lines=csv.split('\n'),txs=[],budgets={total:0,categories:{},monthly:{}};
  lines.forEach(function(line){
    if(!line.trim()||line.startsWith('date,'))return;
    if(line.startsWith('#BUDGETS:')){try{budgets=JSON.parse(line.slice(9));}catch(e){}return;}
    if(line.startsWith('#CATS:')){try{var c=JSON.parse(line.slice(6));CATS.length=0;c.forEach(function(x){CATS.push(x);});saveCatDefs();}catch(e){}return;}
    if(line.startsWith('#ENTITIES:')){try{var e=JSON.parse(line.slice(10));ENTITIES=e;saveEntities();}catch(e){}return;}
    var m=line.match(/^([^,]+),"((?:[^"]|"")*)",([^,]+),([^,]+),([^,]*),?([^,]*)$/);
    if(m)txs.push({date:m[1],description:m[2].replace(/""/g,'"'),amount:parseFloat(m[3]),category:m[4],month:m[5].trim(),entity:m[6]?m[6].trim():'main'});
  });
  return{transactions:txs,budgets:budgets};
}
var _ghSha=null;
async function ghPull(manual){
  var tok=getToken();if(!tok){if(manual)showToast('No token — go to Sync tab');return;}
  setSyncStatus('syncing','pulling…');
  try{
    var r=await fetch(GH_API,{headers:{'Authorization':'Bearer '+tok,'Accept':'application/vnd.github+json'}});
    if(r.status===404){setSyncStatus('ok','no remote file yet');if(manual)showToast('No remote file yet — push first');return;}
    if(!r.ok){setSyncStatus('err','pull failed '+r.status);return;}
    var data=await r.json();_ghSha=data.sha;
    var csv=decodeURIComponent(escape(atob(data.content.replace(/\n/g,''))));
    var parsed=csvToState(csv);
    if(parsed.transactions.length){
      S.transactions=parsed.transactions.map(function(t){return t.category==='utilities'?Object.assign({},t,{category:'rent'}):t;});
      S.budgets=parsed.budgets;
      saveLocalOnly();populateSels();showPage('overview');
// Init Coloris globally with sensible defaults
if(window.Coloris){
  Coloris({theme:'dark',themeMode:'auto',formatToggle:false,closeButton:true,closeLabel:'Done'});
}
      var d=new Date().toLocaleTimeString();
      setSyncStatus('ok','synced '+d);
      var sd=document.getElementById('sync-detail');if(sd)sd.textContent='Pulled '+parsed.transactions.length+' transactions at '+d;
      if(manual)showToast('Pulled from GitHub!');
    }
  }catch(e){setSyncStatus('err','offline');}
}
async function ghPush(manual){
  var tok=getToken();if(!tok){if(manual)showToast('No token — go to Sync tab');return;}
  setSyncStatus('syncing','pushing…');
  try{
    if(!_ghSha){var chk=await fetch(GH_API,{headers:{'Authorization':'Bearer '+tok,'Accept':'application/vnd.github+json'}});if(chk.ok){var cd=await chk.json();_ghSha=cd.sha;}}
    var body={message:'Ledger sync '+new Date().toISOString().slice(0,16),content:btoa(unescape(encodeURIComponent(stateToCSV())))};
    if(_ghSha)body.sha=_ghSha;
    var r=await fetch(GH_API,{method:'PUT',headers:{'Authorization':'Bearer '+tok,'Accept':'application/vnd.github+json','Content-Type':'application/json'},body:JSON.stringify(body)});
    if(r.ok){var rd=await r.json();_ghSha=rd.content.sha;var d=new Date().toLocaleTimeString();setSyncStatus('ok','synced '+d);var sd=document.getElementById('sync-detail');if(sd)sd.textContent='Pushed '+S.transactions.length+' transactions at '+d;if(manual)showToast('Pushed to GitHub!');}
    else{var err=await r.json().catch(function(){return{};});setSyncStatus('err','push failed');if(manual)showToast('Push failed: '+(err.message||r.status));}
  }catch(e){setSyncStatus('err','offline');if(manual)showToast('Offline');}
}
async function ghForceOverwrite(){if(!confirm('Replace ALL local data with GitHub version? Cannot be undone.'))return;_ghSha=null;await ghPull(true);}
function loadState(){
  try{
    var raw=localStorage.getItem('ledger_v4')||sessionStorage.getItem('ledger_v4_backup')||'{}';
    const p=JSON.parse(raw);S={...S,...p};
  }catch(e){}
  if(!S.transactions.length) S.transactions=TX;
  S.transactions=S.transactions.map(function(t){return t.category==='utilities'?Object.assign({},t,{category:'rent'}):t;});
}
function saveLocalOnly(){try{localStorage.setItem('ledger_v4',JSON.stringify({transactions:S.transactions,budgets:S.budgets}));}catch(e){}}
function saveState(){saveLocalOnly();if(saveState._timer)clearTimeout(saveState._timer);saveState._timer=setTimeout(function(){ghPush(false);},3000);}

// ── PERIOD ──
function salaryDateForMk(mk){
  var[y,m]=mk.split('-').map(Number);
  var ms=new Date(y,m-1,1),me=new Date(y,m,0);
  var sal=S.transactions.filter(function(t){var d=parseImportDate(t.date);return t.category==='income'&&t.amount>2000&&d&&d>=ms&&d<=me;});
  if(sal.length){sal.sort(function(a,b){return parseImportDate(a.date)-parseImportDate(b.date);});return parseImportDate(sal[0].date);}
  return new Date(y,m-1,26);
}
function periodForMk(mk){
  var[y,m]=mk.split('-').map(Number);
  // Use calendar month — simpler and more predictable than salary-based periods
  var hasSalary=S.transactions.some(function(t){
    var d=parseImportDate(t.date);
    if(!d)return false;
    return t.category==='income'&&t.amount>2000&&d.getFullYear()===y&&d.getMonth()===m-1;
  });
  return{start:new Date(y,m-1,1),end:new Date(y,m,0),hasSalary:hasSalary};
}
function fmtD(d){return d.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit',year:'numeric'})}
function txInPeriod(mk){
  return S.transactions.filter(function(t){
    // Derive month from date string (handles DD/MM/YYYY correctly)
    if(t.date){
      var d=parseImportDate(t.date);
      if(d){
        var derivedMk=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
        if(derivedMk===mk)return true;
      }
    }
    // Fallback: stored t.month field
    return t.month===mk;
  });
}
function txExp(txs){return txs.filter(t=>t.amount<0&&!['savings','income','loans','cash'].includes(t.category));}
function totalSpent(txs){return txs.filter(function(t){return t.category!=='income';}).reduce(function(s,t){return s+Math.abs(t.amount);},0);}
function fmt(n){return Math.abs(n).toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2})+' €';}

function parseImportDate(s){
  if(!s)return null;
  if(s instanceof Date)return isNaN(s)?null:s;
  s=String(s).trim();
  // YYYY-MM-DD or YYYY/MM/DD
  var m=s.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})$/);
  if(m)return new Date(+m[1],+m[2]-1,+m[3]);
  // DD/MM/YYYY or DD.MM.YYYY or DD-MM-YYYY (Sabadell format)
  m=s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})$/);
  if(m)return new Date(+m[3],+m[2]-1,+m[1]);
  // DD/MM/YY
  m=s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2})$/);
  if(m){var yr=+m[3];yr+=yr<50?2000:1900;return new Date(yr,+m[2]-1,+m[1]);}
  // Excel serial number (days since 1900-01-01)
  if(/^\d+$/.test(s)){
    var serial=+s;
    if(serial>40000&&serial<60000){
      var d=new Date(1899,11,30);d.setDate(d.getDate()+serial);return d;
    }
  }
  // Fallback to native Date (may mis-parse)
  var d=new Date(s);
  return isNaN(d)?null:d;
}

function allMonths(){
  var mks=new Set();
  S.transactions.forEach(function(t){
    if(t.date){
      var d=parseImportDate(t.date);
      if(d)mks.add(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'));
      else if(t.month)mks.add(t.month);
    } else if(t.month){
      mks.add(t.month);
    }
  });
  return[...mks].sort();
}
function todayMk(){
  var d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
}
function curMk(){
  var cm=S.currentMonth;
  if(cm){
    if(cm.startsWith('F:'))return cm;
    if(/^\d{4}-\d{2}$/.test(cm))return cm;
  }
  var months=allMonths();
  var tmk=todayMk();
  var withData=months.filter(function(m){return m<=tmk;});
  return withData.length?withData[withData.length-1]:tmk;
}
function fmtMk(mk){
  if(!mk)return'—';
  const raw=mk.startsWith('F:')?mk.slice(2):mk;
  const[y,m]=raw.split('-');
  return new Date(y,m-1,1).toLocaleString('default',{month:'long',year:'numeric'});
}
function isFore(mk){
  if(!mk)return false;
  if(mk.startsWith('F:'))return true;
  // Only pure future months (strictly after today) are forecast
  return mk>todayMk();
}
function rawMk(mk){return isFore(mk)?mk.slice(2):mk;}

// ── PREDICTIONS ──
function predMonth(mk){
  const months=allMonths();
  const[fy,fm]=mk.split('-').map(Number);
  const days=new Date(fy,fm,0).getDate();
  const lyMk=(fy-1)+'-'+String(fm).padStart(2,'0');
  const lyTx=txInPeriod(lyMk);
  const recent3=months.slice(-3);
  const avgCat=k=>recent3.map(m=>txInPeriod(m).filter(t=>t.category===k).reduce((s,t)=>s+Math.abs(t.amount),0)).reduce((a,b)=>a+b,0)/3;
  const grocAmts=recent3.map(m=>txInPeriod(m).filter(t=>t.category==='groceries').reduce((s,t)=>s+Math.abs(t.amount),0));
  const grocDays=recent3.map(m=>{const[y2,m2]=m.split('-').map(Number);return new Date(y2,m2,0).getDate();});
  const grocPerDay=grocAmts.reduce((a,b)=>a+b,0)/grocDays.reduce((a,b)=>a+b,0);
  const rentLy=lyTx.filter(t=>t.category==='rent').reduce((s,t)=>s+Math.abs(t.amount),0);
  const utilLy=lyTx.filter(t=>t.category==='utilities').reduce((s,t)=>s+Math.abs(t.amount),0);
  const res={};
  CATS.forEach(c=>{
    if(c.key==='groceries') res[c.key]=grocPerDay*days;
    else if(c.key==='rent') res[c.key]=rentLy||avgCat('rent');
    else if(c.key==='utilities') res[c.key]=utilLy||avgCat('utilities');
    else if(c.key==='income') res[c.key]=0;
    else if(c.key==='savings'){var lastSavNet=txInPeriod(months[months.length-1]).filter(function(t){return t.category==='savings';}).reduce(function(s,t){return s+t.amount;},0);res[c.key]=lastSavNet<0?Math.abs(lastSavNet):avgCat('savings');}
    else if(c.key==='cash') res[c.key]=avgCat('cash');
    else res[c.key]=avgCat(c.key);
  });
  return res;
}

// ── NAV ──
function showPage(id){
  _currentPage=id;
  var content=document.getElementById('page-content');
  if(!content)return;
  // Update nav highlights
  document.querySelectorAll('.nav-item,.bn-item').forEach(function(el){
    el.classList.toggle('active', el.dataset.page===id);
  });
  // Fetch page HTML and inject it
  fetch('pages/'+id+'.html?v='+Date.now())
    .then(function(r){return r.text();})
    .then(function(html){
      content.innerHTML=html;
      // Scroll to top
      window.scrollTo(0,0);
      if(content.scrollTop!==undefined)content.scrollTop=0;
      // Page-specific init
      if(id==='overview'){renderOverview();renderUncatBanner();}
      if(id==='budget'){updateCatStatus();renderBudgetPage();}
      if(id==='transactions'){renderTransactions();}
      if(id==='import'){
        renderEntitySelector();renderDataHealth();
        var tok=getToken();
        var tst=document.getElementById('gh-token-status');
        if(tst)tst.textContent=tok?'Token saved — enter a new one to replace it':'No token set yet';
        var sd=document.getElementById('sync-detail');
        if(sd&&tok)sd.textContent='Auto-sync active. Pushes 3s after every change.';
        setupDropZone();
      }
      if(id==='entities'){renderEntitiesPage();}
      if(id==='ai'){setupAiPage();}
    })
    .catch(function(e){
      content.innerHTML='<div style="padding:40px;color:var(--text3)">Page not found: pages/'+id+'.html</div>';
    });
}
var _currentPage='overview';

// ── MONTH SELECTS ──
function populateSels(){
  var months=allMonths();
  var tmk=todayMk();
  var[fy,fm]=tmk.split('-').map(Number);
  // Include today's month in real months even if no data yet
  var allReal=[...new Set([...months,tmk])].sort();
  // Future = 3 months after today
  const future=[1,2,3].map(i=>{const d=new Date(fy,fm-1+i,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');});
  const realOpts=allReal.map(m=>'<option value="'+m+'">'+fmtMk(m)+'</option>').join('');
  const foreOpts=future.map(m=>'<option value="F:'+m+'">▸ '+fmtMk(m)+'</option>').join('');
  const all=realOpts+'<option disabled>── Forecast ──</option>'+foreOpts;
  var cm=curMk();
  ['sel-desk','sel-mob'].forEach(id=>{
    const el=document.getElementById(id);
    if(!el)return;
    el.innerHTML=all;
    // Set value — if not in options (e.g. gap month), add it
    if(cm&&!el.querySelector('option[value="'+cm+'"]')){
      var opt=document.createElement('option');
      opt.value=cm;opt.textContent=fmtMk(cm);
      var div=el.querySelector('option[disabled]');
      div?el.insertBefore(opt,div):el.appendChild(opt);
    }
    if(cm)el.value=cm;
  });
}
function onSelChange(src){
  const v=document.getElementById(src).value;
  S.currentMonth=v;
  ['sel-desk','sel-mob'].forEach(id=>{const el=document.getElementById(id);if(el)el.value=v;});
  renderOverview();renderTransactions();
}

// ── RING ──
function drawRing(data,total){
  const c=document.getElementById('ring-canvas');
  if(!c)return;
  const ctx=c.getContext('2d');
  const W=c.width,cx=W/2,cy=W/2,r=W/2-8,inn=r*0.55;
  ctx.clearRect(0,0,W,W);
  if(!total){ctx.beginPath();ctx.arc(cx,cy,(r+inn)/2,0,Math.PI*2);ctx.strokeStyle='#555';ctx.lineWidth=r-inn;ctx.stroke();return;}
  let ang=-Math.PI/2;
  data.forEach(function(d){
    if(!d.v)return;
    const sw=(d.v/total)*Math.PI*2;
    ctx.beginPath();ctx.arc(cx,cy,(r+inn)/2,ang,ang+sw);
    ctx.strokeStyle=d.col;ctx.lineWidth=r-inn;ctx.stroke();
    ang+=sw;
  });
}

// ── OVERVIEW ──
function renderOverview(){
  const mk=curMk();if(!mk)return;
  // Debug: log transaction counts
  var months=allMonths();
  console.log('[Ledger] S.transactions:',S.transactions.length,'months:',months);
  if(mk==='2026-04'||mk==='2026-05'||mk==='2026-06'||mk==='2026-07'){
    var forMk=S.transactions.filter(function(t){return t.month===mk;});
    console.log('[Ledger] For',mk,':',forMk.length,'by month field');
  }
  const fore=isFore(mk);
  const rmk=rawMk(mk);
  const{start,end,hasSalary}=periodForMk(rmk);

  var yrN=parseInt(rmk.split('-')[0]),moN=parseInt(rmk.split('-')[1])-1;
  var mName=new Date(yrN,moN,1).toLocaleString('default',{month:'long',year:'numeric'}).toUpperCase();
  document.getElementById('ov-title').textContent=(fore?'FORECAST ':'OVERVIEW ')+mName;
  var realMs=allMonths(),isCur=rmk===realMs[realMs.length-1]&&!fore;
  if(fore)document.getElementById('ov-sub').textContent='Predicted — dates shown once salary is booked';
  else if(isCur&&!hasSalary)document.getElementById('ov-sub').textContent='From '+fmtD(start)+' — end date pending salary';
  else document.getElementById('ov-sub').textContent=fmtD(start)+' – '+fmtD(end);

  let catTotals={};
  if(fore){
    catTotals=predMonth(rmk);
  } else {
    var allTxPeriod=txInPeriod(mk);
    // Use Math.abs to handle both positive and negative amount conventions
    allTxPeriod.filter(function(t){return !['income'].includes(t.category);}).forEach(function(t){
      catTotals[t.category]=(catTotals[t.category]||0)+Math.abs(t.amount);
    });
  }

  const spent=getExpCats().reduce(function(s,c){return s+(catTotals[c.key]||0);},0);
  const bud=S.budgets.total;

  // Card 1
  const cv1=document.getElementById('cv1');
  cv1.textContent=fmt(spent);cv1.style.color='#f9a825';
  document.getElementById('cs1').textContent=fore?'estimated':'this period';
  document.getElementById('cw1').style.setProperty('--top','3px solid #f9a825');

  // Card 2
  const cv2=document.getElementById('cv2');
  if(bud>0){
    const rem=bud-spent;
    cv2.textContent=fmt(Math.abs(rem));
    cv2.style.color=rem<0?'#ef5350':'#4fc3a1';
    document.getElementById('cs2').textContent=(rem<0?'over':'under')+' budget ('+fmt(bud)+')';
  } else {
    cv2.textContent='—';cv2.style.color='#eee';
    document.getElementById('cs2').textContent='Set a budget';
  }

  // Card 3 – income
  const cv3=document.getElementById('cv3');
  if(!fore){
    const incTotal=txInPeriod(mk).filter(function(t){return t.category==='income';}).reduce(function(s,t){return s+Math.abs(t.amount);},0);
    cv3.textContent=fmt(incTotal);cv3.style.color='#66bb6a';
    const savNet=txInPeriod(mk).filter(function(t){return t.category==='savings';}).reduce(function(s,t){return s+Math.abs(t.amount);},0);
    document.getElementById('cs3').textContent=savNet?'↓ '+fmt(savNet)+' to savings':'no savings movement';
  } else {
    const salAll=S.transactions.filter(function(t){return t.category==='income'&&t.amount>2000;});
    const avgInc=salAll.length?salAll.reduce(function(s,t){return s+t.amount;},0)/salAll.length:0;
    cv3.textContent=avgInc?fmt(avgInc):'—';cv3.style.color='#66bb6a';
    document.getElementById('cs3').textContent='avg salary (estimated)';
  }

  // Budget bar
  const bbs=document.getElementById('bbar-section');
  var isFuture=mk&&(mk.startsWith('F:')||mk>todayMk());
  if(bud>0&&!isFuture){
    const pct=Math.min(100,spent/bud*100);
    bbs.style.display='block';
    document.getElementById('bbl').textContent=pct.toFixed(0)+'% used';
    document.getElementById('bbr').textContent=fmt(spent)+' / '+fmt(bud);
    const fill=document.getElementById('bfill');
    fill.style.width=pct+'%';
    fill.style.background=pct>90?'#ef5350':pct>70?'#f9a825':'#4fc3a1';
  } else bbs.style.display='none';

  // Ring
  const ringData=getExpCats().map(function(c){return{col:c.color,v:catTotals[c.key]||0};}).filter(function(d){return d.v>0;});
  drawRing(ringData,spent);
  document.getElementById('ring-cv').textContent=fmt(spent);

  // Cat grid
  var budForMk=(S.budgets.monthly&&S.budgets.monthly[rmk])||{};
  const sorted=getExpCats().map(function(c){return Object.assign({},c,{total:catTotals[c.key]||0});}).filter(function(c){return c.total>0||budForMk[c.key]>0;}).sort(function(a,b){return b.total-a.total;});
  const maxC=sorted[0]?sorted[0].total:1;
  const grid=document.getElementById('cat-grid');
  if(!sorted.length){grid.innerHTML='<div class="empty"><div class="empty-msg">No data for this period</div></div>';renderHistBars();return;}
  var isCurMo=!fore&&rmk===allMonths()[allMonths().length-1];
  grid.innerHTML=sorted.map(function(c){
    var pct=Math.min(100,(c.total/maxC*100)).toFixed(0);
    // Budget vs actual for current month
    var budAmt=(S.budgets.monthly&&S.budgets.monthly[rmk]&&S.budgets.monthly[rmk][c.key])||0;
    var budBar='';
    if(isCurMo&&budAmt>0){
      var usedPct=Math.min(100,(c.total/budAmt*100)).toFixed(0);
      var barCol=usedPct>100?'#ef5350':usedPct>80?'#f9a825':c.color;
      budBar='<div style="display:flex;justify-content:space-between;font-size:11px;color:var(--text3);margin-top:4px">'
        +'<span>'+fmt(c.total)+' / '+fmt(budAmt)+'</span>'
        +'<span style="color:'+(c.total>budAmt?'#ef5350':'var(--text3)')+'">'+usedPct+'%</span></div>'
        +'<div style="height:5px;background:var(--surface3);border-radius:99px;margin-top:3px;overflow:hidden">'
        +'<div style="height:100%;width:'+usedPct+'%;background:'+barCol+';border-radius:99px;transition:width .4s"></div></div>';
    } else {
      budBar='<div class="cat-bar"><div class="cat-bar-fill" style="width:'+pct+'%;background:'+c.color+'"></div></div>';
    }
    return '<div class="cat-card" style="border-left-color:'+c.color+';cursor:pointer" onclick="openCatModal(\''+c.key+'\')">'
      +'<div class="ci" style="background:'+c.color+'22;color:'+c.color+'">'+catIcon(c.key,20,c.color)+'</div>'
      +'<div class="cat-info">'
      +'<div class="cat-name">'+c.label+'</div>'
      +'<div class="cat-amt" style="color:'+c.color+'">'+fmt(c.total)+'</div>'
      +budBar
      +'</div></div>';
  }).join('');
  renderHistBars();
  renderAverages();
  renderUncatBanner();
}

// ── STACKED HISTORY BARS ──
function renderHistBars(){
  const months=allMonths();
  var tmkH=todayMk();
  // Fill any gaps between first and today so bar is continuous
  var allReal=[...new Set([...months,tmkH])].sort();
  if(allReal.length>1){
    var first=allReal[0],[gy,gm]=first.split('-').map(Number);
    var filled=[];
    var [ty,tm]=tmkH.split('-').map(Number);
    while(gy<ty||(gy===ty&&gm<=tm)){
      filled.push(gy+'-'+String(gm).padStart(2,'0'));
      gm++;if(gm>12){gm=1;gy++;}
    }
    allReal=[...new Set([...filled,...allReal])].sort();
  }
  // Future = 3 months strictly after today
  var[fy,fm]=tmkH.split('-').map(Number);
  const future=[1,2,3].map(function(i){const d=new Date(fy,fm-1+i,1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');});
  const allMks=[...allReal,...future];
  const data=allMks.map(function(m,idx){
    const fore=m>todayMk();
    var bycat={};
    if(fore){
      const p=predMonth(m);
      getExpCats().forEach(function(c){bycat[c.key]=p[c.key]||0;});
    } else {
      txExp(txInPeriod(m)).forEach(function(t){bycat[t.category]=(bycat[t.category]||0)+Math.abs(t.amount);});
    }
    const total=Object.values(bycat).reduce(function(a,b){return a+b;},0);
    return{mk:m,bycat:bycat,total:total,fore:fore};
  });

  const maxT=Math.max.apply(null,data.map(function(d){return d.total;}));
  if(!maxT){document.getElementById('hist-chart').innerHTML='';document.getElementById('hist-labels').innerHTML='';return;}

  const cm=curMk();
  const chart=document.getElementById('hist-chart');
  const labels=document.getElementById('hist-labels');

  chart.innerHTML=data.map(function(d){
    const h=Math.round(d.total/maxT*74);
    const navKey=d.fore?'F:'+d.mk:d.mk;
    const isActive=(d.mk===cm)||(isFore(cm)&&rawMk(cm)===d.mk);
    const outline=isActive?'outline:2px solid #eee;outline-offset:1px;':'';
    const segs=getExpCats().filter(function(c){return(d.bycat[c.key]||0)>0;}).map(function(c){
      const sh=Math.max(1,Math.round((d.bycat[c.key]/d.total)*h));
      return '<div class="hseg" style="height:'+sh+'px;background:'+c.color+';opacity:'+(d.fore?0.55:0.88)+'"></div>';
    }).join('');
    return '<div class="hcol" style="flex:1" onclick="navToMonth(\''+navKey+'\')">'
      +'<div class="hstack" style="height:'+h+'px;'+outline+'">'+(segs||'<div style="height:28px;background:var(--surface3);border-radius:3px"></div>')+'</div>'
      +'</div>';
  }).join('');

  var prevLblYear=null;
  labels.innerHTML=data.map(function(d){
    const[y,mo]=d.mk.split('-');
    const lbl=new Date(y,mo-1).toLocaleString('default',{month:'short'});
    const isActive=(d.mk===cm)||(isFore(cm)&&rawMk(cm)===d.mk);
    const showYr=y!==prevLblYear;prevLblYear=y;
    return '<div style="flex:1;text-align:center;font-family:var(--num);color:'+(isActive?'var(--text)':'var(--text3)') + '">'
      +(showYr?'<div style="font-size:8px;color:var(--text2)">'+y+'</div>':'')
      +'<div style="font-size:9px">'+lbl+(d.fore?'*':'')+'</div>'
      +'</div>';
  }).join('');
}

function navToMonth(mk){
  S.currentMonth=mk;
  // Ensure month is in dropdown (may be a gap-filled month)
  ['sel-desk','sel-mob'].forEach(function(id){
    var el=document.getElementById(id);
    if(!el)return;
    // Add option if missing
    if(!el.querySelector('option[value="'+mk+'"]')){
      var opt=document.createElement('option');
      opt.value=mk;opt.textContent=fmtMk(mk);
      // Insert before forecast divider
      var divider=el.querySelector('option[disabled]');
      divider?el.insertBefore(opt,divider):el.appendChild(opt);
    }
    el.value=mk;
  });
  renderOverview();
}

// ── CAT MODAL ──
let _modalCatKey='';
function openCatModal(catKey){
  _modalCatKey=catKey;
  var mk=curMk();var fore=isFore(mk);
  var c=catMeta(catKey);
  var mi=document.getElementById('modal-cat-icon');
  mi.innerHTML=catIcon(catKey,22,c.color);mi.style.background=c.color+'33';
  document.getElementById('modal-cat-title').textContent=c.label;
  document.getElementById('modal-cat-title').style.color=c.color;
  if(fore){
    var pred=predMonth(rawMk(mk));var amt=pred[catKey]||0;
    document.getElementById('modal-cat-total').textContent=fmt(amt)+' est.';
    document.getElementById('modal-cat-total').style.color=c.color;
    var basis=catKey==='rent'?'Same month last year':catKey==='groceries'?'Daily rate × days in month':catKey==='loans'?'Last month':catKey==='dog'?'Same month last year':catKey==='subscriptions'?'Last month':'3-month average';
    var[fry,frm]=rawMk(mk).split('-').map(Number);
    var lyMkF=(fry-1)+'-'+String(frm).padStart(2,'0');
    var lyTxsF=txInPeriod(lyMkF).filter(function(t){return t.category===catKey&&t.amount<0;}).slice().sort(function(a,b){return new Date(a.date)-new Date(b.date);});
    var lyRows=lyTxsF.map(function(t){var gi=S.transactions.indexOf(t);return '<div class="mtx" style="opacity:0.75"><div class="mtx-date" style="color:var(--text3)">ly '+t.date.slice(5).replace('-','.')+'</div><div class="mtx-desc" style="color:var(--text2)">'+t.description+'</div><div class="mtx-amt" style="color:#b0bec5">−'+fmt(Math.abs(t.amount))+'</div>'+(gi>=0?'<button class="mtx-btn" onclick="openScope('+gi+')">&#9998;</button>':'')+'</div>';}).join('');
    document.getElementById('modal-tx-list').innerHTML='<div style="padding:12px 16px 8px;border-bottom:1px solid var(--border)"><div style="font-family:var(--num);font-size:20px;color:'+c.color+'">'+fmt(amt)+'</div><div style="font-size:13px;color:var(--text3);margin-top:3px">Basis: '+basis+'</div></div>'+(lyRows?'<div style="font-size:12px;color:var(--text3);padding:8px 16px 4px;font-family:var(--num);text-transform:uppercase;letter-spacing:1px">Reference (last year)</div>'+lyRows:'<div style="padding:16px;color:var(--text3);font-size:15px">No reference data from last year</div>');
  } else {
    var txs=txInPeriod(mk).filter(function(t){return t.category===catKey;}).slice().sort(function(a,b){return new Date(b.date)-new Date(a.date);});
    var total=txs.reduce(function(s,t){return s+Math.abs(t.amount);},0);
    document.getElementById('modal-cat-total').textContent=fmt(total);
    document.getElementById('modal-cat-total').style.color=c.color;
    var today=new Date();today.setHours(0,0,0,0);
    var happened=txs.filter(function(t){return new Date(t.date)<=today;});
    var isCurrentMo=rawMk(mk)===allMonths()[allMonths().length-1];
    var expectedRows='';
    if(isCurrentMo){
      var ms=allMonths();var prevMk=ms[ms.length-2];
      if(prevMk){
        var prevTxs=txInPeriod(prevMk).filter(function(t){return t.category===catKey&&t.amount<0;});
        var hapDescs=happened.map(function(t){return t.description.toLowerCase().trim();});
        var expected=prevTxs.filter(function(t){return!hapDescs.includes(t.description.toLowerCase().trim());});
        if(expected.length){
          expectedRows='<div style="font-size:12px;color:var(--text3);padding:8px 16px 4px;font-family:var(--num);text-transform:uppercase;letter-spacing:1px;background:var(--surface2)">Expected this month</div>'
            +expected.map(function(t){return '<div class="mtx" style="opacity:0.65"><div class="mtx-date" style="color:var(--text3)">exp</div><div class="mtx-desc" style="color:var(--text2)">'+t.description+'</div><div class="mtx-amt" style="color:#b0bec5">≈ −'+fmt(Math.abs(t.amount))+'</div></div>';}).join('');
        }
      }
    }
    var hapHeader=isCurrentMo?'<div style="font-size:12px;color:var(--text3);padding:8px 16px 4px;font-family:var(--num);text-transform:uppercase;letter-spacing:1px;background:var(--surface2)">Booked</div>':'';
    document.getElementById('modal-tx-list').innerHTML=expectedRows+(txs.length?hapHeader+happened.map(function(t){var gi=S.transactions.indexOf(t);var pos=t.amount>0;return '<div class="mtx"><div class="mtx-date">'+t.date.slice(5).replace('-','.')+'</div><div class="mtx-desc" style="color:var(--text)">'+t.description+'</div><div class="mtx-amt" style="color:'+(pos?'#4fc3a1':'#ef5350')+'">'+(pos?'+':'−')+fmt(Math.abs(t.amount))+'</div>'+(gi>=0?'<button class="mtx-btn" onclick="openScope('+gi+')">&#9998;</button>':'')+'</div>';}).join(''):'<div style="padding:16px;color:var(--text3);font-size:15px">No bookings yet in this category</div>');
  }
  openModal('cat-modal');
}

// ── SCOPE / RECLASSIFY ──
function openScope(globalIdx){
  const t=S.transactions[globalIdx];
  if(!t)return;
  _pending={txDate:t.date,txDesc:t.description,txIdx:globalIdx,newCat:''};
  closeModal('cat-modal');
  document.getElementById('scope-desc').textContent=t.description;
  var identEl=document.getElementById('scope-ident');
  identEl.value=t.description;
  identEl.oninput=updateScopeCount;
  document.getElementById('scope-one-only').checked=false;
  document.getElementById('scope-apply-btns').innerHTML='';
  document.getElementById('scope-match-count').textContent='';
  document.getElementById('scope-cat-grid').innerHTML=CATS.map(function(c){
    return '<div class="scope-cat" style="border-left-color:'+c.color+'" onclick="pickCat(this,\''+c.key+'\')">'  
      +catIcon(c.key,14,c.color)+' <span style="font-size:11px">'+c.label+'</span></div>';
  }).join('');
  openModal('scope-modal');
}
function pickCat(el,key){
  _pending.newCat=key;
  document.querySelectorAll('.scope-cat').forEach(function(b){b.classList.remove('sel');});
  el.classList.add('sel');
  updateScopeCount();
  document.getElementById('scope-apply-btns').innerHTML=
    '<button class="btn btn-p" onclick="applyScope()" style="width:100%;margin-top:4px;font-size:16px">Apply</button>';
}
function updateScopeCount(){
  var oneOnly=document.getElementById('scope-one-only').checked;
  var ident=(document.getElementById('scope-ident').value||'').trim();
  var el=document.getElementById('scope-match-count');
  if(oneOnly||!ident){el.textContent='Applies to this booking only';return;}
  var n=S.transactions.filter(function(t){return t.description.includes(ident);}).length;
  el.textContent=n+' transaction'+(n!==1?'s':'')+' match this identifier';
}
function applyScope(){
  var oneOnly=document.getElementById('scope-one-only').checked;
  var ident=(document.getElementById('scope-ident').value||'').trim();
  var newCat=_pending.newCat;
  if(!newCat){showToast('Pick a category first');return;}
  var changed=0;
  var applyPastEl=document.getElementById('scope-apply-past');
  var applyPast=!applyPastEl||applyPastEl.checked;
  S.transactions=S.transactions.map(function(t,i){
    if(oneOnly){
      if(i===_pending.txIdx){changed++;return Object.assign({},t,{category:newCat});}
      return t;
    }
    if(ident&&t.description.includes(ident)&&(applyPast||i===_pending.txIdx)){changed++;return Object.assign({},t,{category:newCat});}
    return t;
  });
  if(!oneOnly&&ident){
    var ci=CATS.findIndex(function(c){return c.key===newCat;});
    if(ci>=0){
      if(!CATS[ci].markers)CATS[ci].markers=[];
      if(!CATS[ci].markers.includes(ident)){CATS[ci].markers.push(ident);saveCatDefs();}
    }
  }
  saveState();closeModal('scope-modal');
  showToast(changed+' transaction'+(changed!==1?'s':'')+' updated ✓');
  renderOverview();renderTransactions();
  if(_modalCatKey)setTimeout(function(){openCatModal(_modalCatKey);},200);
}

function openModal(id){document.getElementById(id).classList.add('open');}
function closeModal(id){document.getElementById(id).classList.remove('open');}

// ── TRANSACTIONS ──
function renderTransactions(){
  var months=allMonths();
  var tmkT=todayMk();
  var allRealT=[...new Set([...months,tmkT])].sort();
  if(allRealT.length>1){
    var filled=[];var[gy,gm]=allRealT[0].split('-').map(Number);
    var[ty,tm]=tmkT.split('-').map(Number);
    while(gy<ty||(gy===ty&&gm<=tm)){filled.push(gy+'-'+String(gm).padStart(2,'0'));gm++;if(gm>12){gm=1;gy++;}}
    allRealT=[...new Set([...filled,...allRealT])].sort();
  }
  const cm=isFore(curMk())?rawMk(curMk()):curMk();
  document.getElementById('tx-pills').innerHTML=allRealT.map(function(m){
    return '<div class="mpill'+(m===cm?' active':'')+'" onclick="setTxMk(\''+m+'\')">'
      +fmtMk(m)+'</div>';
  }).join('');
  const txs=cm?txInPeriod(cm).slice().sort(function(a,b){var da=parseImportDate(a.date),db=parseImportDate(b.date);return (db||0)-(da||0);}):[];
  const{start,end}=periodForMk(cm||months[months.length-1]);
  document.getElementById('tx-sub').textContent=fmtD(start)+' – '+fmtD(end)+' · '+txs.length+' entries';
  const list=document.getElementById('tx-list');
  if(!txs.length){list.innerHTML='<div class="empty"><div class="empty-msg">No transactions</div></div>';return;}
  list.innerHTML=txs.map(function(t){
    const c=catMeta(t.category);
    const gi=S.transactions.indexOf(t);
    const pos=t.amount>0;
    return '<div class="txi">'
      +'<div class="txi-date">'+t.date.slice(5).replace('-','.')+'</div>'
      +'<div class="txi-desc">'
        +'<div class="txi-main">'+t.description+'</div>'
        +'<div class="txi-cat"><div class="txi-dot" style="background:'+c.color+'"></div>'+c.label+'</div>'
      +'</div>'
      +'<div class="txi-amt" style="color:'+(pos?'#4fc3a1':'#ef5350')+'">'+(pos?'+':'−')+fmt(Math.abs(t.amount))+'</div>'
      +'<button class="txi-chg" onclick="openScope('+gi+')">✎</button>'
      +'</div>';
  }).join('');
}
function setTxMk(m){S.currentMonth=m;['sel-desk','sel-mob'].forEach(function(id){const el=document.getElementById(id);if(el)el.value=m;});renderTransactions();}

// ── BUDGET ──
var _budMk=null;
function budMonths(){var ms=allMonths(),last=ms[ms.length-1],ly=parseInt(last.split('-')[0]),lm=parseInt(last.split('-')[1]),r=[last];for(var i=1;i<=5;i++){var d=new Date(ly,lm-1+i,1);r.push(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'));}return r;}
function suggestBudget(k,mk){var ms=allMonths(),ly=parseInt(mk.split('-')[0]),lm=parseInt(mk.split('-')[1]),lyMk=(ly-1)+'-'+String(lm).padStart(2,'0'),last=ms[ms.length-1];var sum=function(m,k){return txInPeriod(m).filter(function(t){return t.category===k&&t.amount<0;}).reduce(function(s,t){return s+Math.abs(t.amount);},0);};var avg3=function(k){return ms.slice(-3).map(function(m){return sum(m,k);}).reduce(function(a,b){return a+b;},0)/3;};if(k==='rent')return sum(lyMk,'rent')||sum(last,'rent');if(k==='loans')return sum(last,'loans');if(k==='dog')return sum(lyMk,'dog')||avg3('dog');if(k==='subscriptions')return sum(last,'subscriptions');if(k==='groceries'){var days=new Date(ly,lm,0).getDate(),r3=ms.slice(-3),ga=r3.map(function(m){return sum(m,'groceries');}),gd=r3.map(function(m){var p=parseInt(m.split('-')[0]),q=parseInt(m.split('-')[1]);return new Date(p,q,0).getDate();});return ga.reduce(function(a,b){return a+b;},0)/gd.reduce(function(a,b){return a+b;},0)*days;}return(S.budgets.monthly&&S.budgets.monthly[mk]&&S.budgets.monthly[mk][k])||0;}
var AUTO_CATS=['rent','loans','dog','subscriptions','groceries'],MANUAL_CATS=['health','shopping','transport','travel','cash','other'];
function renderBudgetPage(){
  var bms=budMonths();if(!_budMk||!bms.includes(_budMk))_budMk=bms[0];
  document.getElementById('bud-month-pills').innerHTML=bms.map(function(m){var ly=parseInt(m.split('-')[0]),lm=parseInt(m.split('-')[1]),lbl=new Date(ly,lm-1,1).toLocaleString('default',{month:'short',year:'2-digit'});return '<div class="mpill'+(m===_budMk?' active':'')+'" onclick="setBudMk(\''+m+'\')" style="font-size:11px;padding:4px 9px">'+lbl+'</div>';}).join('');
  var mk=_budMk,saved=(S.budgets.monthly&&S.budgets.monthly[mk])||{};
  var autoHtml=AUTO_CATS.map(function(k){var c=catMeta(k),sug=suggestBudget(k,mk),val=saved[k]!==undefined?saved[k]:sug;return '<div class="brow"><div class="blbl" style="color:'+c.color+'">'+c.label+' <span style="font-size:9px;color:var(--text3)">AUTO</span></div><div style="display:flex;gap:6px;align-items:center"><input type="number" class="binput" id="bc-'+k+'" value="'+Math.round(val||0)+'" placeholder="0">'+(sug?'<span style="font-size:10px;color:var(--text3);white-space:nowrap">≈ '+fmt(sug)+'</span>':'')+'</div></div>';}).join('');
  var manHtml=MANUAL_CATS.map(function(k){var c=catMeta(k),val=saved[k]!==undefined?saved[k]:0;return '<div class="brow"><div class="blbl" style="color:'+c.color+'">'+c.label+'</div><input type="number" class="binput" id="bc-'+k+'" value="'+Math.round(val||0)+'" placeholder="0"></div>';}).join('');
  // Build icon-box grid like overview
  var allBudCats=AUTO_CATS.concat(MANUAL_CATS);
  var budCards=allBudCats.map(function(k){
    var c=catMeta(k),sug=suggestBudget(k,mk),val=saved[k]!==undefined?saved[k]:sug;
    var isAuto=AUTO_CATS.indexOf(k)>=0;
    return '<div class="cat-card" style="border-left-color:'+c.color+';flex-direction:column;align-items:stretch;gap:6px;cursor:default">'
      +'<div style="display:flex;align-items:center;gap:8px">'
      +'<div class="ci" style="background:'+c.color+'22;color:'+c.color+'">'+catIcon(k,20,c.color)+'</div>'
      +'<div style="flex:1">'
      +'<div class="cat-name">'+c.label+(isAuto?' <span style="font-size:11px;color:var(--text3)">AUTO</span>':'')+'</div>'
      +(sug&&isAuto?'<div style="font-size:12px;color:var(--text3);font-family:var(--num)">≈ '+fmt(sug)+'</div>':'')
      +'</div>'
      +'<button style="background:transparent;border:none;color:var(--text3);font-size:18px;cursor:pointer;padding:2px 6px;border-radius:6px" onclick="openCatEdit(\''+k+'\')" title="Edit">&#9998;</button>'
      +'</div>'
      +'<input type="number" class="binput" id="bc-'+k+'" value="'+Math.round(val||0)+'" placeholder="0" style="width:100%;">'
      +'</div>';
  }).join('');
  document.getElementById('bud-cat-grid').innerHTML=budCards;
  var total=allBudCats.reduce(function(s,k){var val=saved[k]!==undefined?saved[k]:suggestBudget(k,mk);return s+(val||0);},0);
  document.getElementById('bud-total-auto').textContent='Est. total: '+fmt(total);
}
function setBudMk(mk){_budMk=mk;renderBudgetPage();}
function saveTotalBud(){saveCatBuds();}
function saveCatBuds(){if(!S.budgets.monthly)S.budgets.monthly={};if(!S.budgets.monthly[_budMk])S.budgets.monthly[_budMk]={};AUTO_CATS.concat(MANUAL_CATS).forEach(function(k){var el=document.getElementById('bc-'+k);if(el){var v=parseFloat(el.value);S.budgets.monthly[_budMk][k]=isNaN(v)?0:v;}});S.budgets.total=Object.values(S.budgets.monthly[_budMk]).reduce(function(a,b){return a+b;},0);saveState();showToast('Budget saved for '+fmtMk(_budMk)+'!');}
// ── IMPORT ──
const dz=document.getElementById('drop-zone');
dz.addEventListener('dragover',function(e){e.preventDefault();dz.classList.add('drag');});
dz.addEventListener('dragleave',function(){dz.classList.remove('drag');});
dz.addEventListener('drop',function(e){e.preventDefault();dz.classList.remove('drag');handleFile({target:{files:e.dataTransfer.files}});});
// ── COLUMN MAPPING MEMORY ──
function colMapKey(headers){return headers.slice().sort().join('|');}
function saveColMap(headers,mapping){
  var maps=JSON.parse(localStorage.getItem('ledger_colmaps')||'{}');
  maps[colMapKey(headers)]=mapping;
  localStorage.setItem('ledger_colmaps',JSON.stringify(maps));
}
function loadColMap(headers){
  var maps=JSON.parse(localStorage.getItem('ledger_colmaps')||'{}');
  return maps[colMapKey(headers)]||null;
}


function handleFile(ev){
  var file=ev.target.files[0];if(!file)return;
  var ext=file.name.split('.').pop().toLowerCase();
  function dHdr(a){for(var i=0;i<Math.min(15,a.length);i++){var j=a[i].map(String).join(' ').toLowerCase();if(j.includes('fecha')||j.includes('concepto')||j.includes('importe')||j.includes('f. operativa')||j.includes('date')||j.includes('description')||j.includes('amount')||j.includes('buchung'))return i;}return 0;}
  function toO(a,hi){var hs=a[hi].map(function(h,i){return String(h).trim()||('Col'+i);});return a.slice(hi+1).filter(function(r){return r.some(function(c){return String(c).trim();});}).map(function(r){var o={};hs.forEach(function(h,i){o[h]=r[i]!==undefined?r[i]:'';});return o;});}
  if(ext==='csv'){Papa.parse(file,{header:false,skipEmptyLines:false,complete:function(r){var hi=dHdr(r.data),obs=toO(r.data,hi);setupMap(obs.length?Object.keys(obs[0]):[],obs);}});}
  else{var rd=new FileReader();rd.onload=function(e){var wb=XLSX.read(e.target.result,{type:'binary',cellDates:true}),ws=wb.Sheets[wb.SheetNames[0]],aoa=XLSX.utils.sheet_to_json(ws,{header:1,defval:''}),hi=dHdr(aoa),obs=toO(aoa,hi);setupMap(obs.length?Object.keys(obs[0]):[],obs);};rd.readAsBinaryString(file);}
}
function guessCol(h,f){h=h.toLowerCase();if(f==='date')return h.includes('date')||h.includes('datum');if(f==='description')return h.includes('desc')||h.includes('merchant')||h.includes('memo')||h.includes('name');if(f==='amount')return h.includes('amount')||h.includes('betrag')||h.includes('value');return false;}
function setupMap(headers,rows){
  S.csvRows=rows;
  S.csvHeaders=headers;
  document.getElementById('map-section').style.display='block';
  var saved=loadColMap(headers);
  const fields=[{key:'date',label:'Date'},{key:'description',label:'Description'},{key:'amount',label:'Amount'}];
  document.getElementById('map-grid').innerHTML=fields.map(function(f){
    var savedVal=saved?saved[f.key]:'';
    return '<div class="map-row"><div class="map-lbl">'+f.label+'</div><select class="map-sel" id="mp-'+f.key+'" onchange="updatePrev()"><option value="">— select —</option>'+headers.map(function(hd){
      var isSaved=savedVal&&savedVal===hd;
      var isGuess=!savedVal&&guessCol(hd,f.key);
      return'<option value="'+hd+'"'+((isSaved||isGuess)?' selected':'')+'>'+hd+'</option>';
    }).join('')+'</select></div>';
  }).join('');
  if(saved){
    document.getElementById('map-grid').insertAdjacentHTML('afterbegin',
      '<div style="font-size:12px;color:#4fc3a1;margin-bottom:8px;font-family:var(--num)">✓ Column mapping remembered from previous import</div>');
  }
  updatePrev();
}
function updatePrev(){
  // Show date parse preview
  var dc=document.getElementById('mp-date').value;
  if(dc&&S.csvRows&&S.csvRows.length){
    var sampleDate=String(S.csvRows[0][dc]||'');
    var parsed=parseImportDate(sampleDate);
    var prevEl=document.getElementById('date-parse-preview');
    if(!prevEl){
      var mg=document.getElementById('map-grid');
      if(mg){var d=document.createElement('div');d.id='date-parse-preview';d.style.cssText='font-size:12px;color:var(--text3);font-family:var(--num);margin-bottom:8px';mg.appendChild(d);}
      prevEl=document.getElementById('date-parse-preview');
    }
    if(prevEl)prevEl.textContent=parsed
      ?'Date preview: "'+sampleDate+'" → '+parsed.toISOString().slice(0,10)+' ✓'
      :'Date preview: "'+sampleDate+'" → could not parse ✗';
  }
  const cols=['date','description','amount'].map(function(k){const el=document.getElementById('mp-'+k);return el?el.value:'';}).filter(Boolean);
  if(!cols.length)return;
  document.getElementById('prev-box').style.display='block';
  const rows=(S.csvRows||[]).slice(0,5);
  document.getElementById('prev-tbl').innerHTML='<table style="border-collapse:collapse;width:100%"><tr>'
    +cols.map(function(c){return'<th style="padding:4px 8px;border-bottom:1px solid var(--border);text-align:left;color:var(--text3)">'+c+'</th>';}).join('')+'</tr>'
    +rows.map(function(r){return'<tr>'+cols.map(function(c){return'<td style="padding:4px 8px;border-bottom:1px solid var(--border)">'+(r[c]||'')+'</td>';}).join('')+'</tr>';}).join('')+'</table>';
}
async function runImport(){
  const dc=document.getElementById('mp-date').value;
  const desc=document.getElementById('mp-description').value;
  const ac=document.getElementById('mp-amount').value;
  if(!dc||!desc||!ac){showToast('Map all columns first');return;}
  // Save column mapping for this header set
  saveColMap(S.csvHeaders||[],{date:dc,description:desc,amount:ac});
  const st=document.getElementById('imp-status');
  st.innerHTML='<span class="spin"></span> Parsing…';
  const raw=(S.csvRows||[]).map(function(r){
    const rd=r[dc]?String(r[dc]):'';
    const ra=String(r[ac]).replace(',','.').replace(/[^0-9.\-]/g,'');
    const amt=parseFloat(ra);
    // Parse date: handle DD/MM/YYYY (Sabadell), DD.MM.YYYY, YYYY-MM-DD
    var parsedDate=parseImportDate(rd);
    const mk=parsedDate?parsedDate.getFullYear()+'-'+String(parsedDate.getMonth()+1).padStart(2,'0'):'0000-00';
    const dateStr=parsedDate?parsedDate.getFullYear()+'-'+String(parsedDate.getMonth()+1).padStart(2,'0')+'-'+String(parsedDate.getDate()).padStart(2,'0'):rd;
    return{date:dateStr,description:String(r[desc]||''),amount:isNaN(amt)?0:amt,month:mk,category:'other'};
  }).filter(function(r){return r.month>='2025-01'&&r.description;});
  if(!raw.length){st.textContent='No valid rows found';return;}
  // Dedup against existing
  const existing=new Set(S.transactions.map(function(t){return t.date+'|'+t.description+'|'+t.amount;}));
  const newRows=raw.filter(function(r){return!existing.has(r.date+'|'+r.description+'|'+r.amount);});
  if(!newRows.length){st.textContent='No new transactions found';return;}
  // AI pre-categorize
  // Step 1: apply saved markers
  var markerMatched=0;
  newRows.forEach(function(r){
    CATS.forEach(function(cat){
      if(cat.markers&&cat.markers.length){
        if(cat.markers.some(function(m){return r.description.includes(m);})){
          r.category=cat.key;markerMatched++;
        }
      }
    });
  });
  // Step 2: AI for remaining 'other' rows
  var needsAI=newRows.filter(function(r){return r.category==='other';});
  if(needsAI.length){
    st.innerHTML='<span class="spin"></span> AI categorising '+needsAI.length+' unmatched…';
    for(var i=0;i<needsAI.length;i+=30){
      var batch=needsAI.slice(i,i+30);
      var cats=await catBatch(batch.map(function(r){return r.description;}));
      cats.forEach(function(c,j){if(needsAI[i+j])needsAI[i+j].category=c;});
    }
  }
  st.textContent='';
  // SAVE ALL NEW ROWS IMMEDIATELY before review
  // This ensures data is never lost if user navigates away during review
  S.transactions=S.transactions.concat(newRows);
  saveLocalOnly();
  populateSels();
  showToast(newRows.length+' transactions saved! Now categorising…');
  
  // Step 3: review only marker-unmatched rows (categories update in-place)
  _isUncatReview=true;  // treat as uncat review so finishImport updates in-place
  var forReview=newRows.filter(function(r){
    return !CATS.some(function(cat){
      return cat.markers&&cat.markers.some(function(m){return r.description.includes(m);});
    });
  });
  _markerMatchedRows=[];
  if(forReview.length){
    _reviewRows=forReview;
    _reviewTotalStart=forReview.length;
    var seen={};_reviewQueue=[];
    forReview.forEach(function(r){if(!seen[r.description]){seen[r.description]=true;_reviewQueue.push(r);}});
    _reviewIdx=0;_revIdent=null;
    showPage('budget');
    var rs=document.getElementById('review-section');
    if(rs)rs.style.display='block';
    showReviewItem();
  } else {
    showToast(markerMatched+' auto-matched!');
    _isUncatReview=false;
    renderOverview();
    showPage('overview');
  }
}

// ── INTERACTIVE CATEGORISATION REVIEW ──
var _reviewRows=[];
var _markerMatchedRows=[];
var _reviewIdx=0;
var _reviewQueue=[]; // unique descriptions not yet confirmed
var _reviewMap={};   // desc->category map confirmed so far

function startCatReview(rows){
  _reviewRows=rows;
  _reviewMap={};
  // Build queue: one representative per unique description
  var seen={};
  _reviewQueue=[];
  rows.forEach(function(r){
    if(!seen[r.description]){seen[r.description]=true;_reviewQueue.push(r);}
  });
  _reviewIdx=0;
  showPage('import');
  document.getElementById('map-section').style.display='none';
  document.getElementById('review-section').style.display='block';
  showReviewItem();
}

function showReviewItem(){
  var prog=document.getElementById('rev-progress');
  var card=document.getElementById('rev-card');
  var txLeft=_reviewRows.filter(function(r){return r.category==='other'||!r.category;}).length;
  var txTot=_reviewTotalStart||_reviewRows.length;
  var txDone=txTot-txLeft;
  var pct2=txTot>0?Math.round((txDone/txTot)*100):0;
  if(prog)prog.textContent=txDone+' of '+txTot+' · '+txLeft+' remaining';
  // Skip queue items where all rows already categorised
  while(_reviewIdx<_reviewQueue.length){
    var qr=_reviewQueue[_reviewIdx];
    var hasUncat=_reviewRows.some(function(r){return r.description===qr.description&&(r.category==='other'||!r.category);});
    if(hasUncat)break;
    _reviewIdx++;
  }
  if(txLeft===0||_reviewIdx>=_reviewQueue.length){finishImport();return;}
  var r=_reviewQueue[_reviewIdx];
  // Count how many uncategorised rows share this exact description
  var sameCount=_reviewRows.filter(function(x){return x.description===r.description&&(x.category==='other'||!x.category);}).length;
  var c=catMeta(r.category);
  card.innerHTML=
    // Progress
    '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">'
    +'<div style="font-size:13px;color:var(--text3);font-family:var(--num)">'+txDone+' / '+txTot+' · <strong style="color:var(--text)">'+txLeft+' remaining</strong></div>'
    +'<div style="font-size:13px;color:var(--text2);font-family:var(--num);font-weight:600">'+pct2+'%</div>'
    +'</div>'
    +'<div style="height:4px;background:var(--surface3);border-radius:99px;margin-bottom:14px;overflow:hidden">'
    +'<div style="height:100%;width:'+pct2+'%;background:#f9a825;border-radius:99px;transition:width .3s"></div></div>'
    // Date + amount
    +'<div style="display:flex;gap:16px;margin-bottom:12px">'
    +'<div><div style="font-size:11px;color:var(--text3);font-family:var(--num);margin-bottom:2px">DATE</div>'
    +'<div style="font-size:15px;font-family:var(--num)">'+r.date+'</div></div>'
    +'<div><div style="font-size:11px;color:var(--text3);font-family:var(--num);margin-bottom:2px">AMOUNT</div>'
    +'<div style="font-size:15px;font-family:var(--num);color:'+(r.amount<0?'#ef5350':'#4fc3a1')+'">'+(r.amount<0?'−':'+')+fmt(Math.abs(r.amount))+'</div></div>'
    +(sameCount>1?'<div><div style="font-size:11px;color:var(--text3);font-family:var(--num);margin-bottom:2px">SAME DESC</div><div style="font-size:15px;font-family:var(--num);color:#f9a825">'+sameCount+' bookings</div></div>':'')
    +'</div>'
    // Full description — tap to copy to identifier
    +'<div style="margin-bottom:10px">'
    +'<div style="font-size:11px;color:var(--text3);font-family:var(--num);margin-bottom:4px">DESCRIPTION — tap to copy to identifier</div>'
    +'<div id="rev-desc" onclick="var inp=document.getElementById(\'rev-ident-inp\');if(inp){inp.value='+JSON.stringify(r.description)+';revUpdateMatchCount();}" style="font-size:14px;line-height:1.5;padding:10px;background:var(--surface2);border-radius:8px;cursor:pointer;word-break:break-all;user-select:text">'+escHtml(r.description)+'</div>'
    +'<div style="font-size:11px;color:var(--text3);margin-top:3px">Tap the description to use it as identifier, or select part of it</div>'
    +'</div>'
    // Identifier — starts EMPTY
    +'<div style="margin-bottom:12px">'
    +'<div style="font-size:11px;color:var(--text3);font-family:var(--num);margin-bottom:4px">IDENTIFIER — type the text that identifies this merchant</div>'
    +'<div style="display:flex;gap:6px;align-items:center">'
    +'<input id="rev-ident-inp" type="text" value="" placeholder="e.g. CONDIS, YOIGO, AMZN…" '
    +'style="flex:1;font-family:var(--num);font-size:15px;background:var(--surface2);border:1px solid var(--border);color:var(--text);padding:10px 12px;border-radius:8px;outline:none" '
    +'oninput="revUpdateMatchCount()">'
    +'<button onclick="var inp=document.getElementById(\'rev-ident-inp\');inp.value='+JSON.stringify(r.description)+';revUpdateMatchCount();" '
    +'title="Reset to full description" '
    +'style="background:none;border:1px solid var(--border);color:var(--text3);cursor:pointer;padding:10px 12px;border-radius:8px;font-size:13px;white-space:nowrap">↺ Full</button>'
    +'</div>'
    +'<div id="rev-match-count" style="font-size:12px;color:var(--text3);margin-top:4px;font-family:var(--num)"></div>'
    +'</div>'
    // One-only checkbox
    +'<label style="display:flex;align-items:center;gap:10px;margin-bottom:12px;padding:10px 12px;background:var(--surface2);border-radius:8px;cursor:pointer">'
    +'<input type="checkbox" id="rev-one-only" style="width:20px;height:20px;flex-shrink:0" onchange="revUpdateMatchCount()">'
    +'<div><div style="font-size:14px;color:var(--text);font-weight:500">This booking only</div>'
    +'<div style="font-size:12px;color:var(--text3);margin-top:1px">Tick to change only this one — no rule saved, identifier ignored</div></div>'
    +'</label>'
    // Category grid
    +'<div style="margin-bottom:14px">'
    +'<div style="font-size:11px;color:var(--text3);font-family:var(--num);margin-bottom:8px">CATEGORY (suggested: <span style="color:'+c.color+'">'+c.label+'</span>)</div>'
    +'<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">'
    +CATS.filter(function(cc){return cc.key!=='utilities';}).map(function(cc){
      return '<div onclick="revPickCat(\''+cc.key+'\')" style="display:flex;align-items:center;gap:6px;padding:8px 12px;border-radius:8px;border:2px solid '+(cc.key===r.category?cc.color:'var(--border)')+';background:'+(cc.key===r.category?cc.color+'22':'var(--surface2)')+';cursor:pointer;transition:all .15s">'
        +catIcon(cc.key,16,cc.color)
        +'<span style="font-size:14px;color:var(--text)">'+cc.label+'</span></div>';
    }).join('')
    +'<div onclick="openAddCatFromReview()" style="padding:8px 12px;border-radius:8px;border:2px dashed var(--border);cursor:pointer;font-size:14px;color:var(--text3)">+ New</div>'
    +'</div></div>'
    +'<div class="btn-row">'
    +'<button class="btn btn-p" onclick="revConfirm()" style="flex:1">Confirm & Next →</button>'
    +'<button class="btn btn-g" onclick="revSkipAll()">Skip remaining</button>'
    +'</div>';
  // Also handle text selection from description
  var descEl=document.getElementById('rev-desc');
  if(descEl){
    descEl.addEventListener('mouseup',function(){
      var sel=window.getSelection(),txt=sel?sel.toString().trim():'';
      if(txt.length>1){var inp=document.getElementById('rev-ident-inp');if(inp){inp.value=txt;revUpdateMatchCount();}}
    });
    descEl.addEventListener('touchend',function(){
      setTimeout(function(){
        var sel=window.getSelection(),txt=sel?sel.toString().trim():'';
        if(txt.length>1){var inp=document.getElementById('rev-ident-inp');if(inp){inp.value=txt;revUpdateMatchCount();}}
      },100);
    });
  }
  revUpdateMatchCount();
}

function revUpdateMatchCount(){
  var oneOnly=document.getElementById('rev-one-only');
  var inp=document.getElementById('rev-ident-inp');
  var el=document.getElementById('rev-match-count');
  if(!el)return;
  if(oneOnly&&oneOnly.checked){el.textContent='This booking only — no rule created';return;}
  var ident=inp?inp.value.trim():'';
  if(!ident){el.textContent='Empty identifier — will not match anything';return;}
  var n=_reviewRows.filter(function(t){return t.description.includes(ident);}).length;
  var nUncat=_reviewRows.filter(function(t){return t.description.includes(ident)&&(t.category==='other'||!t.category);}).length;
  el.textContent=n+' total match ('+nUncat+' uncategorised) — all will get this category';
}


function escHtml(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}

var _revIdent=null;

function revPickCat(catKey){
  var r=_reviewQueue[_reviewIdx];
  if(!r)return;
  r.category=catKey;
  // Re-render category grid to show selection
  var card=document.getElementById('rev-card');
  if(!card)return;
  card.querySelectorAll('[onclick^="revPickCat"]').forEach(function(el){
    var k=el.getAttribute('onclick').match(/'([^']+)'/)[1];
    var cc=catMeta(k);
    el.style.borderColor=k===catKey?cc.color:'var(--border)';
    el.style.background=k===catKey?cc.color+'22':'var(--surface2)';
  });
}

function saveReviewState(){
  try{localStorage.setItem('ledger_review',JSON.stringify({
    rows:_reviewRows,
    qidx:_reviewQueue.map(function(r){return _reviewRows.indexOf(r);}),
    idx:_reviewIdx,matched:_markerMatchedRows
  }));}catch(e){}
}
function loadReviewState(){
  try{
    var s=JSON.parse(localStorage.getItem('ledger_review')||'null');
    if(!s||!s.rows||!s.rows.length)return false;
    _reviewRows=s.rows;
    _reviewQueue=s.qidx.map(function(i){return _reviewRows[i];}).filter(Boolean);
    _reviewIdx=s.idx||0;_markerMatchedRows=s.matched||[];
    return true;
  }catch(e){return false;}
}
function clearReviewState(){localStorage.removeItem('ledger_review');}
function doResumeReview(){
  if(loadReviewState()){
    document.getElementById('rev-resume-banner').style.display='none';
    document.getElementById('map-section').style.display='none';
    document.getElementById('review-section').style.display='block';
    showReviewItem();
  }
}
function revConfirm(){
  var r=_reviewQueue[_reviewIdx];
  if(!r)return;
  var oneOnlyEl=document.getElementById('rev-one-only');
  var isOneOnly=oneOnlyEl&&oneOnlyEl.checked;
  var beforeCat=_reviewRows.filter(function(r){return r.category==='other'||!r.category;}).length;
  var identInp=document.getElementById('rev-ident-inp');
  var ident=identInp?identInp.value.trim():'';
  var cat=r.category;
  if(isOneOnly){
    var key=r.date+'|'+r.description+'|'+r.amount;
    _reviewRows.forEach(function(row){
      if(row.date+'|'+row.description+'|'+row.amount===key)row.category=cat;
    });
  } else {
    _reviewRows.forEach(function(row){
      if(row.description.includes(ident)||row.description===r.description)row.category=cat;
    });
    var ci=CATS.findIndex(function(c){return c.key===cat;});
    if(ci>=0){
      if(!CATS[ci].markers)CATS[ci].markers=[];
      if(!CATS[ci].markers.includes(ident)){CATS[ci].markers.push(ident);saveCatDefs();}
    }
  }
  var afterCat=_reviewRows.filter(function(r){return r.category==='other'||!r.category;}).length;
  var jump=(typeof beforeCat!=='undefined')?(beforeCat-afterCat):0;
  if(jump>1)showToast(jump+' transactions categorised ✓');
  _revIdent=null;_reviewIdx++;
  saveReviewState();
  showReviewItem();
}

function revSkipAll(){
  _reviewIdx=_reviewQueue.length;
  clearReviewState();
  finishImport();
}

function openAddCatFromReview(){
  // Open add cat modal; on save, re-open review
  _afterAddCat=function(){
    // Re-render current review item so new cat appears
    showReviewItem();
  };
  openAddCat();
}
var _afterAddCat=null;

function finishImport(){
  var rs=document.getElementById('review-section');
  if(rs)rs.style.display='none';
  if(_isUncatReview){
    // Apply reviewed categories back to S.transactions in-place
    var catMap={};
    _reviewRows.forEach(function(r){catMap[r.date+'|'+r.description+'|'+r.amount]=r.category;});
    S.transactions=S.transactions.map(function(t){
      var k=t.date+'|'+t.description+'|'+t.amount;
      return catMap[k]?Object.assign({},t,{category:catMap[k]}):t;
    });
    _isUncatReview=false;
    clearReviewState();saveLocalOnly();renderOverview();renderUncatBanner();
    showToast('Categorisation saved!');updateCatStatus();showPage('overview');
  } else {
    var all=_markerMatchedRows.concat(_reviewRows);
    S.transactions=S.transactions.concat(all);
    clearReviewState();
    saveLocalOnly(); // Save immediately, don't wait for debounce
    if(saveState._timer)clearTimeout(saveState._timer);
    ghPush(false); // Also push to GitHub
    populateSels();
    renderDataHealth();
    showToast(all.length+' transactions imported! ('+S.transactions.length+' total)');showPage('overview');
  }
}
async function catBatch(descs){
  const prompt='Categorize each into one of: groceries,dog,health,shopping,subscriptions,transport,travel,rent,utilities,loans,savings,income,cash,other\n'+descs.map(function(d,i){return(i+1)+'. '+d;}).join('\n')+'\nJSON array only.';
  try{
    const res=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:'claude-sonnet-4-20250514',max_tokens:1000,messages:[{role:'user',content:prompt}]})});
    const data=await res.json();
    const text=(data.content||[]).map(function(b){return b.text||'';}).join('')||'[]';
    const arr=JSON.parse(text.replace(/```json|```/g,'').trim());
    if(Array.isArray(arr)&&arr.length===descs.length)return arr.map(function(c){return CATS.find(function(x){return x.key===c;})?c:'other';});
  }catch(e){}
  return descs.map(function(){return'other';});
}
