// ── AI ──
async function sendAI(){
  const inp=document.getElementById('ai-inp');const msg=inp.value.trim();if(!msg)return;inp.value='';
  appendAI('user',msg);aiHistory.push({role:'user',content:msg});
  appendAI('assistant','<span class="spin"></span>');
  const months=allMonths();
  const lines=months.map(function(m){
    const txs=txInPeriod(m);
    const bycat={};
    txExp(txs).forEach(function(t){bycat[t.category]=(bycat[t.category]||0)+Math.abs(t.amount);});
    const cats=Object.entries(bycat).map(function(e){return e[0]+' '+fmt(e[1]);}).join(', ');
    return fmtMk(m)+': spent '+fmt(totalSpent(txs))+'. '+cats+'.';
  });
  const ctx=lines.join(' | ');
  const sys='You are a personal finance assistant. Sabadell account data: '+ctx+(ctx?'':' No data.')
    +' Budget: '+(S.budgets.total?fmt(S.budgets.total):'not set')+'. Be concise, use real numbers.';
  try{
    const res=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:'claude-sonnet-4-20250514',max_tokens:1000,system:sys,messages:aiHistory})});
    const data=await res.json();
    const reply=(data.content||[]).map(function(b){return b.text||'';}).join('')||'No response.';
    document.getElementById('ai-msgs').lastElementChild.remove();
    appendAI('assistant',reply);aiHistory.push({role:'assistant',content:reply});
  }catch(e){
    document.getElementById('ai-msgs').lastElementChild.remove();
    appendAI('assistant','Connection error.');
  }
}
function appendAI(role,text){
  const msgs=document.getElementById('ai-msgs');
  const div=document.createElement('div');
  div.className='ai-msg '+role;div.innerHTML=text;
  msgs.appendChild(div);msgs.scrollTop=msgs.scrollHeight;
}

// ── EXPORT CSV ──
function exportCSV(){
  const header='date,description,amount,category,month';
  const rows=S.transactions.map(function(t){return t.date+',"'+t.description.replace(/"/g,'""')+'",'+t.amount+','+t.category+','+t.month;});
  const blob=new Blob([header+'\n'+rows.join('\n')],{type:'text/csv'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');a.href=url;a.download='ledger.csv';a.click();
  URL.revokeObjectURL(url);showToast('CSV exported!');
}

// ── TOAST ──
function showToast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(function(){t.classList.remove('show');},3000);}
function toggleTheme(){
  var light=document.body.classList.toggle('light');
  localStorage.setItem('ledger_theme',light?'light':'dark');
  var label=light?'☀ Light mode':'☽ Dark mode';
  ['theme-btn','theme-btn-mob'].forEach(function(id){var el=document.getElementById(id);if(el)el.textContent=label;});
}
function applyTheme(){
  var t=localStorage.getItem('ledger_theme');
  if(t==='light'){document.body.classList.add('light');
    ['theme-btn','theme-btn-mob'].forEach(function(id){var el=document.getElementById(id);if(el)el.textContent='☀ Light mode';});}
}



// ── GRID COLOR PICKER ──
var GCP_COLORS=["#ff0000", "#ff7f00", "#ffff00", "#00ff00", "#00ffff", "#007fff", "#0000ff", "#7f00ff", "#ff00ff", "#ff007f", "#ffffff", "#e60000", "#e67300", "#e6e600", "#00e600", "#00e6e6", "#0073e6", "#0000e6", "#7300e6", "#e600e6", "#e60073", "#e2e2e2", "#ce0000", "#ce6700", "#cece00", "#00ce00", "#00cece", "#0067ce", "#0000ce", "#6700ce", "#ce00ce", "#ce0067", "#c6c6c6", "#b60000", "#b65b00", "#b6b600", "#00b600", "#00b6b6", "#005bb6", "#0000b6", "#5b00b6", "#b600b6", "#b6005b", "#aaaaaa", "#9e0000", "#9e4f00", "#9e9e00", "#009e00", "#009e9e", "#004f9e", "#00009e", "#4f009e", "#9e009e", "#9e004f", "#8d8d8d", "#860000", "#864300", "#868600", "#008600", "#008686", "#004386", "#000086", "#430086", "#860086", "#860043", "#717171", "#6e0000", "#6e3700", "#6e6e00", "#006e00", "#006e6e", "#00376e", "#00006e", "#37006e", "#6e006e", "#6e0037", "#555555", "#560000", "#562b00", "#565600", "#005600", "#005656", "#002b56", "#000056", "#2b0056", "#560056", "#56002b", "#383838", "#3e0000", "#3e1f00", "#3e3e00", "#003e00", "#003e3e", "#001f3e", "#00003e", "#1f003e", "#3e003e", "#3e001f", "#1c1c1c", "#260000", "#261300", "#262600", "#002600", "#002626", "#001326", "#000026", "#130026", "#260026", "#260013", "#000000"];
var _gcpFn=null,_gcpInputId=null,_gcpPreviewId=null,_gcpSel=null;

function openGCP(currentColor,fnName,inputId,previewId){
  _gcpFn=fnName;_gcpInputId=inputId;_gcpPreviewId=previewId;_gcpSel=currentColor||'#4fc3a1';
  var ov=document.createElement('div');
  ov.className='gcp-overlay';ov.id='gcp-overlay';
  var gridHtml=GCP_COLORS.map(function(col){
    var isSel=col.toLowerCase()===(_gcpSel||'').toLowerCase();
    return '<div class="gcp-swatch'+(isSel?' sel':'')+'" style="background:'+col+'" data-col="'+col+'" onclick="gcpPick(this,\''+col+'\')"></div>';
  }).join('');
  ov.innerHTML=
    '<div class="gcp-box">'
    +'<div class="gcp-grid">'+gridHtml+'</div>'
    +'<div class="gcp-bottom">'
    +'<div class="gcp-preview" id="gcp-preview" style="background:'+_gcpSel+'"></div>'
    +'<input class="gcp-hex" id="gcp-hex" value="'+_gcpSel.toUpperCase()+'" maxlength="7" spellcheck="false">'
    +'</div>'
    +'<div class="gcp-btns">'
    +'<button class="gcp-ok" onclick="gcpOK()">OK</button>'
    +'<button class="gcp-cancel" onclick="gcpClose()">Cancel</button>'
    +'</div>'
    +'</div>';
  document.body.appendChild(ov);
  // Hex input live update
  document.getElementById('gcp-hex').addEventListener('input',function(e){
    var v=e.target.value.trim();
    if(!/^#/.test(v))v='#'+v;
    if(/^#[0-9a-fA-F]{6}$/.test(v)){
      _gcpSel=v;
      document.getElementById('gcp-preview').style.background=v;
      if(_gcpFn)window[_gcpFn]({},v);
    }
  });
}
function gcpPick(el,col){
  _gcpSel=col;
  document.querySelectorAll('.gcp-swatch').forEach(function(s){s.classList.remove('sel');});
  el.classList.add('sel');
  document.getElementById('gcp-preview').style.background=col;
  document.getElementById('gcp-hex').value=col.toUpperCase();
  if(_gcpFn)window[_gcpFn]({},col);
}
function gcpOK(){
  var col=_gcpSel;
  if(_gcpInputId){var inp=document.getElementById(_gcpInputId);if(inp)inp.value=col;}
  if(_gcpPreviewId){var pr=document.getElementById(_gcpPreviewId);if(pr)pr.style.background=col;}
  if(_gcpFn)window[_gcpFn]({},col);
  gcpClose();
}
function gcpClose(){var ov=document.getElementById('gcp-overlay');if(ov)ov.remove();}

function buildColorGrid(gid,selCol,fnName){
  var g=document.getElementById(gid);if(!g)return;
  var inputId=gid+'-val';
  var previewId=gid+'-preview';
  var cur=selCol||'#4fc3a1';
  g.innerHTML=
    '<div style="display:flex;gap:12px;align-items:center">'
    +'<div id="'+previewId+'" style="width:64px;height:64px;border-radius:10px;background:'+cur+';border:2px solid var(--border);flex-shrink:0;cursor:pointer" onclick="openGCP(document.getElementById(\''+inputId+'\').value,\''+fnName+'\',\''+inputId+'\',\''+previewId+'\')"></div>'
    +'<input id="'+inputId+'" type="text" value="'+cur+'" maxlength="7"'
    +' style="flex:1;font-family:var(--num);font-size:22px;background:var(--surface2);border:1px solid var(--border);color:var(--text);padding:14px 16px;border-radius:8px;outline:none;cursor:pointer"'
    +' onclick="openGCP(this.value,\''+fnName+'\',\''+inputId+'\',\''+previewId+'\')"'
    +' oninput="var v=this.value;if(/^#[0-9a-fA-F]{6}$/.test(v)){var p=document.getElementById(\''+previewId+'\');if(p)p.style.background=v;window[\''+fnName+'\']({},v);}">'
    +'</div>';
}
