// ── CATEGORY EDITOR ──
var CAT_ICONS_LIST=['basket','paw','cross','bag','wifi','car','plane','home','card','bank','euro','cash','box','signal'];
var CAT_COLORS_LIST=['#4fc3a1','#26c6da','#42a5f5','#7e57c2','#ab47bc','#f06292','#ec407a','#ef5350','#ff7043','#ff8a65','#f9a825','#ffd54f','#9ccc65','#66bb6a','#a5d6a7','#80cbc4','#b0bec5','#8d6e63','#78909c','#546e7a','#263238','#ffffff'];
var _editCatKey=null,_editNewIcon=null,_editNewColor=null;

function buildIconGrid(gid,selIco,fn,col){
  var g=document.getElementById(gid);if(!g)return;
  var color=col||_editNewColor||'#aaa';
  g.innerHTML=CAT_ICONS_LIST.map(function(ic){
    var svg=ICONS[ic]?'<div style="width:22px;height:22px;color:'+color+'">'+ICONS[ic]+'</div>':ic;
    return '<div class="icon-btn'+(ic===selIco?' sel':'')+'" onclick="'+fn+'(this,\''+ic+'\')">'+svg+'</div>';
  }).join('');
}

function cpSwatchClick(el,gid,fnName,col){
  var g=document.getElementById(gid);
  if(g)g.querySelectorAll('div[title]').forEach(function(s){s.style.borderColor='transparent';});
  el.style.borderColor='var(--text)';
  var prev=document.getElementById(gid+'-preview');if(prev)prev.style.background=col;
  var nat=document.getElementById(gid+'-native');if(nat)nat.value=col;
  var hex=document.getElementById(gid+'-hex');if(hex)hex.value=col;
  window[fnName]({},col);
}
function selIcon(el,ic){_editNewIcon=ic;document.querySelectorAll('#ceme-icons .icon-btn').forEach(function(b){b.classList.remove('sel');});el.classList.add('sel');var eiEl=document.getElementById('cemeIcon');if(eiEl)eiEl.innerHTML=ICONS[ic]?'<div style="width:26px;height:26px;color:'+(document.querySelector('#ceme-colors .sel')?document.querySelector('#ceme-colors .sel').style.background:_editNewColor||'#aaa')+'">'+ICONS[ic]+'</div>':ic;}
