function selAddIcon(el,ic){_editNewIcon=ic;document.querySelectorAll('#addcat-icons .icon-btn').forEach(function(b){b.classList.remove('sel');});el.classList.add('sel');}
function selAddColor(el,col){_editNewColor=col;}

function openCatEdit(catKey){
  _editCatKey=catKey;
  var c=catMeta(catKey);
  _editNewIcon=c.icon;_editNewColor=c.color;
  document.getElementById('cemeTitle').textContent='Edit: '+c.label;
  var eiEl=document.getElementById('cemeIcon');
  eiEl.innerHTML=catIcon(catKey,26,c.color);
  document.getElementById('ceme-name').value=c.label;
  buildIconGrid('ceme-icons',c.icon,'selIcon');
  buildColorGrid('ceme-colors',c.color,'selColor');
  renderCemeMarkers(c.markers||[]);
  document.getElementById('ceme-marker-inp').value='';
  var txCount=S.transactions.filter(function(t){return t.category===catKey;}).length;
  var dw=document.getElementById('ceme-delete-wrap');
  if(txCount===0){
    dw.innerHTML='<button class="del-btn" onclick="deleteCat(\''+catKey+'\')">Delete this category</button>';
  } else {
    dw.innerHTML='<div style="font-size:13px;color:var(--text3);padding:6px 0 4px">This category has '+txCount+' booking'+(txCount!==1?'s':'')+'. Deleting moves them to Other.</div>'
      +'<button class="del-btn" onclick="forceDeleteCat(\''+catKey+'\','+txCount+')">Delete & move bookings to Other</button>';
  }
  openModal('cat-edit-modal');
}
function renderCemeMarkers(markers){
  var g=document.getElementById('ceme-markers');if(!g)return;
  if(!markers||!markers.length){g.innerHTML='<div style="font-size:13px;color:var(--text3);margin-bottom:4px">No markers yet — add text snippets to auto-assign this category</div>';return;}
  g.innerHTML=markers.map(function(m,i){
    return '<span style="display:inline-flex;align-items:center;gap:4px;background:var(--surface2);border:1px solid var(--border);border-radius:99px;padding:4px 10px;font-family:var(--num);font-size:13px;margin:0 4px 4px 0">'
      +escHtml(m)
      +'<span onclick="cemeRemoveMarker('+i+')" style="cursor:pointer;color:var(--text3);font-size:14px;margin-left:2px">✕</span>'
      +'</span>';
  }).join('');
}
function cemeAddMarker(){
  var inp=document.getElementById('ceme-marker-inp');
  var val=inp.value.trim();if(!val)return;
  var idx=CATS.findIndex(function(c){return c.key===_editCatKey;});
  if(idx<0)return;
  if(!CATS[idx].markers)CATS[idx].markers=[];
  if(!CATS[idx].markers.includes(val))CATS[idx].markers.push(val);
  inp.value='';
  renderCemeMarkers(CATS[idx].markers);
}
function cemeRemoveMarker(i){
  var idx=CATS.findIndex(function(c){return c.key===_editCatKey;});
  if(idx<0)return;
  CATS[idx].markers.splice(i,1);
  renderCemeMarkers(CATS[idx].markers);
}
function saveCatEdit(){
  if(!_editCatKey)return;
  var name=document.getElementById('ceme-name').value.trim();
  if(!name){showToast('Enter a name');return;}
  var ci=document.getElementById('ceme-colors-val');if(ci&&ci.value)_editNewColor=ci.value.trim();
  var idx=CATS.findIndex(function(c){return c.key===_editCatKey;});
  if(idx>=0){CATS[idx].label=name;if(_editNewIcon)CATS[idx].icon=_editNewIcon;if(_editNewColor)CATS[idx].color=_editNewColor;}
  saveCatDefs();closeModal('cat-edit-modal');showToast('Category updated!');renderBudgetPage();renderOverview();
}
function deleteCat(catKey){
  if(!confirm('Delete this category?'))return;
  if(S.transactions.filter(function(t){return t.category===catKey;}).length>0){showToast('Use "Delete & move" below');return;}
  var i=CATS.findIndex(function(c){return c.key===catKey;});
  if(i>=0)CATS.splice(i,1);
  saveCatDefs();closeModal('cat-edit-modal');showToast('Category deleted');renderBudgetPage();renderOverview();
}
function forceDeleteCat(catKey,count){
  if(!confirm('Delete and move '+count+' booking'+(count!==1?'s':'')+' to Other?'))return;
  S.transactions=S.transactions.map(function(t){return t.category===catKey?Object.assign({},t,{category:'other'}):t;});
  var i=CATS.findIndex(function(c){return c.key===catKey;});
  if(i>=0)CATS.splice(i,1);
  saveCatDefs();saveState();closeModal('cat-edit-modal');
  showToast('Deleted, bookings moved to Other');renderBudgetPage();renderOverview();
}
function openAddCat(){
  _editNewIcon='📦';_editNewColor='#78909c';
  document.getElementById('addcat-name').value='';
  buildIconGrid('addcat-icons','📦','selAddIcon');
  buildColorGrid('addcat-colors','#78909c','selAddColor');
  openModal('add-cat-modal');
}
function saveNewCat(){
  var name=document.getElementById('addcat-name').value.trim();
  if(!name){showToast('Enter a name');return;}
  var ci=document.getElementById('addcat-colors-val');if(ci&&ci.value)_editNewColor=ci.value.trim();
  var key='cat_'+Date.now();
  CATS.push({key:key,label:name,icon:_editNewIcon||'📦',color:_editNewColor||'#78909c'});
  saveCatDefs();closeModal('add-cat-modal');showToast('Category added!');
  if(_afterAddCat){var fn=_afterAddCat;_afterAddCat=null;fn();}else{renderBudgetPage();renderOverview();}
}
