// ── SIDEBAR RESIZE/TOGGLE ──
var _sidebarW=220;
var _draggingSidebar=false;
var _dragStartX=0,_dragStartW=0;

function toggleSidebar(){
  var sb=document.getElementById('sidebar');
  var tog=document.getElementById('sidebar-toggle');
  var main=document.querySelector('.main');
  if(sb.classList.contains('collapsed')){
    sb.classList.remove('collapsed');
    sb.style.width=_sidebarW+'px';
    main.style.marginLeft=_sidebarW+'px';
    tog.style.left=(_sidebarW+8)+'px';
    tog.textContent='←';
    localStorage.setItem('sidebar_open','1');
  } else {
    sb.classList.add('collapsed');
    sb.style.width='0';
    main.style.marginLeft='0';
    tog.style.left='8px';
    tog.textContent='☰';
    localStorage.setItem('sidebar_open','0');
  }
}
function initSidebar(){
  var w=parseInt(localStorage.getItem('sidebar_w')||'220');
  var open=localStorage.getItem('sidebar_open')!=='0';
  _sidebarW=Math.max(160,Math.min(400,w));
  var sb=document.getElementById('sidebar');
  var tog=document.getElementById('sidebar-toggle');
  var main=document.querySelector('.main');
  if(open){
    sb.classList.remove('collapsed');
    sb.style.width=_sidebarW+'px';
    main.style.marginLeft=_sidebarW+'px';
    tog.style.left=(_sidebarW+8)+'px';
    tog.textContent='←';
  } else {
    sb.classList.add('collapsed');
    sb.style.width='0';
    main.style.marginLeft='0';
    tog.style.left='8px';
    tog.textContent='☰';
  }
  // Drag handle
  var drag=document.getElementById('sidebar-drag');
  if(drag){
    drag.addEventListener('mousedown',function(e){
      if(sb.classList.contains('collapsed'))return;
      _draggingSidebar=true;
      _dragStartX=e.clientX;
      _dragStartW=sb.offsetWidth;
      drag.classList.add('dragging');
      e.preventDefault();
    });
  }
  document.addEventListener('mousemove',function(e){
    if(!_draggingSidebar)return;
    var newW=Math.max(160,Math.min(400,_dragStartW+(e.clientX-_dragStartX)));
    _sidebarW=newW;
    sb.style.width=newW+'px';
    main.style.marginLeft=newW+'px';
    tog.style.left=(newW+8)+'px';
  });
  document.addEventListener('mouseup',function(){
    if(_draggingSidebar){
      _draggingSidebar=false;
      document.getElementById('sidebar-drag').classList.remove('dragging');
      localStorage.setItem('sidebar_w',String(_sidebarW));
    }
  });
}

// ── AVERAGES ──
function renderAverages(){
  var months=allMonths();
  var el=document.getElementById('ov-averages');
  if(!el||months.length<2)return;
  var realMs=months.filter(function(m){return m<=todayMk();});
  if(realMs.length<1)return;
  var totals=realMs.map(function(m){return totalSpent(txInPeriod(m));});
  var sum=totals.reduce(function(a,b){return a+b;},0);
  var avg=sum/realMs.length;
  var minV=Math.min.apply(null,totals);
  var maxV=Math.max.apply(null,totals);
  var cur=totalSpent(txInPeriod(curMk()));
  var aboveBelow=cur>avg?'↑ '+fmt(cur-avg)+' above':'↓ '+fmt(avg-cur)+' below';

  // Category averages
  var expCats=getExpCats();
  var catAvgRows=expCats.map(function(c){
    var catTotals=realMs.map(function(m){
      return txInPeriod(m).filter(function(t){return t.category===c.key;}).reduce(function(s,t){return s+Math.abs(t.amount);},0);
    });
    var catAvg=catTotals.reduce(function(a,b){return a+b;},0)/realMs.length;
    var catCur=txInPeriod(curMk()).filter(function(t){return t.category===c.key;}).reduce(function(s,t){return s+Math.abs(t.amount);},0);
    var pctOfTotal=avg>0?(catAvg/avg*100):0;
    if(catAvg<1)return null;
    return {c:c,avg:catAvg,cur:catCur,pct:pctOfTotal};
  }).filter(Boolean).sort(function(a,b){return b.avg-a.avg;});

  el.innerHTML=
    // Summary cards row
    '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:14px">'
    +'<div style="flex:1;min-width:130px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r);padding:12px 14px">'
    +'<div style="font-size:12px;color:var(--text3);font-family:var(--num);text-transform:uppercase;letter-spacing:.8px;margin-bottom:4px">Avg / month</div>'
    +'<div style="font-size:22px;font-family:var(--num);color:var(--text)">'+fmt(avg)+'</div>'
    +'<div style="font-size:13px;color:var(--text3);margin-top:2px">over '+realMs.length+' months</div>'
    +'</div>'
    +'<div style="flex:1;min-width:130px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r);padding:12px 14px">'
    +'<div style="font-size:12px;color:var(--text3);font-family:var(--num);text-transform:uppercase;letter-spacing:.8px;margin-bottom:4px">This vs avg</div>'
    +'<div style="font-size:22px;font-family:var(--num);color:'+(cur>avg?'#ef5350':'#4fc3a1')+'">'+aboveBelow+'</div>'
    +'<div style="font-size:13px;color:var(--text3);margin-top:2px">current: '+fmt(cur)+'</div>'
    +'</div>'
    +'<div style="flex:1;min-width:130px;background:var(--surface);border:1px solid var(--border);border-radius:var(--r);padding:12px 14px">'
    +'<div style="font-size:12px;color:var(--text3);font-family:var(--num);text-transform:uppercase;letter-spacing:.8px;margin-bottom:4px">Range</div>'
    +'<div style="font-size:15px;font-family:var(--num);color:#4fc3a1">Low '+fmt(minV)+'</div>'
    +'<div style="font-size:15px;font-family:var(--num);color:#ef5350;margin-top:2px">High '+fmt(maxV)+'</div>'
    +'</div>'
    +'</div>'
    // Category breakdown
    +'<div style="background:var(--surface);border:1px solid var(--border);border-radius:var(--r);padding:14px">'
    +'<div style="font-size:13px;color:var(--text3);font-family:var(--num);text-transform:uppercase;letter-spacing:.8px;margin-bottom:12px">Avg spend per category / month</div>'
    +catAvgRows.map(function(row){
      var barW=Math.min(100,row.pct).toFixed(1);
      var curDiff=row.cur-row.avg;
      var diffStr=curDiff>1?'↑'+fmt(curDiff):curDiff<-1?'↓'+fmt(Math.abs(curDiff)):'≈';
      var diffCol=curDiff>row.avg*0.2?'#ef5350':curDiff<-row.avg*0.2?'#4fc3a1':'var(--text3)';
      var catKey=row.c.key;
    return '<div onclick="openCatModal(\''+catKey+'\')"'
      +' style="display:flex;align-items:center;gap:10px;margin-bottom:8px;cursor:pointer;padding:6px;border-radius:8px">'
      +'<div style="width:28px;height:28px;border-radius:6px;background:'+row.c.color+'22;display:flex;align-items:center;justify-content:center;flex-shrink:0">'+catIcon(catKey,16,row.c.color)+'</div>'
      +'<div style="flex:1;min-width:0">'
      +'<div style="display:flex;justify-content:space-between;margin-bottom:3px">'
      +'<span style="font-size:14px;color:var(--text);font-weight:500">'+row.c.label+'</span>'
      +'<span style="font-family:var(--num);font-size:14px;color:var(--text2)">'+fmt(row.avg)+'</span>'
      +'</div>'
      +'<div style="height:6px;background:var(--surface3);border-radius:99px;overflow:hidden">'
      +'<div style="height:100%;width:'+barW+'%;background:'+row.c.color+';border-radius:99px"></div>'
      +'</div>'
      +'<div style="font-size:12px;color:'+diffCol+';margin-top:2px;font-family:var(--num)">this month: '+diffStr+'</div>'
      +'</div>'
      +'</div>';
    }).join('')
    +'</div>';
}

