// ── DATA REPAIR ──
function repairTransactionDates(){
  // Fix transactions with wrong t.month by re-deriving from t.date
  var repaired=0;
  S.transactions=S.transactions.map(function(t){
    if(!t.date)return t;
    var d=parseImportDate(t.date);
    if(!d)return t;
    var correctMk=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');
    var correctDate=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
    var changed=false;
    var updated=Object.assign({},t);
    if(updated.month!==correctMk){updated.month=correctMk;changed=true;}
    // Also normalize date to YYYY-MM-DD
    if(updated.date!==correctDate&&!/^\d{4}-\d{2}-\d{2}$/.test(updated.date)){
      updated.date=correctDate;changed=true;
    }
    if(changed)repaired++;
    return changed?updated:t;
  });
  if(repaired>0){
    console.log('[Ledger] Repaired dates on '+repaired+' transactions');
    saveLocalOnly();
    setTimeout(function(){showToast('Fixed dates on '+repaired+' transactions');},500);
  }
}

