function saveEntity(){
  var name=document.getElementById('em-name').value.trim();
  if(!name){showToast('Enter a name');return;}
  var desc=document.getElementById('em-desc').value.trim();
  var allowUpload=document.getElementById('em-upload').checked;
  if(_editEntityKey){
    var idx=ENTITIES.findIndex(function(e){return e.key===_editEntityKey;});
    if(idx>=0){
      ENTITIES[idx].label=name;ENTITIES[idx].color=_emColor;
      ENTITIES[idx].description=desc;ENTITIES[idx].allowUpload=allowUpload;
      if(_emIconData)ENTITIES[idx].icon=_emIconData;
    }
  } else {
    ENTITIES.push({key:'ent_'+Date.now(),label:name,icon:_emIconData||null,
      color:_emColor,description:desc,allowUpload:allowUpload,colMap:{}});
  }
  saveEntities();closeModal('entity-modal');
  renderEntitiesPage();renderEntitySelector();
  showToast('Entity saved!');
}

function deleteEntity(key){
  if(!confirm('Delete this entity?'))return;
  ENTITIES=ENTITIES.filter(function(e){return e.key!==key;});
  saveEntities();closeModal('entity-modal');renderEntitiesPage();renderEntitySelector();
  showToast('Entity deleted');
}

function deleteEntityMove(key){
  if(!confirm('Delete entity and move all its transactions to Main Account?'))return;
  S.transactions=S.transactions.map(function(t){return t.entity===key?Object.assign({},t,{entity:'main'}):t;});
  ENTITIES=ENTITIES.filter(function(e){return e.key!==key;});
  saveEntities();saveLocalOnly();closeModal('entity-modal');
  renderEntitiesPage();renderEntitySelector();showToast('Deleted, transactions moved to Main');
}

