function exportJSON(){
  var data={transactions:S.transactions,budgets:S.budgets,cats:CATS,exported:new Date().toISOString()};
  var blob=new Blob([JSON.stringify(data)],{type:'application/json'});
  var a=document.createElement('a');a.href=URL.createObjectURL(blob);
  a.download='ledger-backup-'+todayMk()+'.json';a.click();
  showToast('Backup exported!');
}
function importJSON(inp){
  var file=inp.files[0];if(!file)return;
  var reader=new FileReader();
  reader.onload=function(e){
    try{
      var data=JSON.parse(e.target.result);
      if(data.transactions&&data.transactions.length){
        S.transactions=data.transactions;
        S.budgets=data.budgets||S.budgets;
        if(data.cats&&data.cats.length){CATS.length=0;data.cats.forEach(function(c){CATS.push(c);});saveCatDefs();}
        saveLocalOnly();populateSels();renderOverview();renderDataHealth();
        showToast(data.transactions.length+' transactions restored!');
      } else showToast('Invalid backup file');
    }catch(err){showToast('Could not read: '+err.message);}
    inp.value='';
  };
  reader.readAsText(file);
}
function updateCatStatus(){
  var bar=document.getElementById('cat-status-bar');
  var txt=document.getElementById('cat-status-text');
  var act=document.getElementById('cat-status-action');
  if(!bar||!txt||!act)return;
  var uncat=S.transactions.filter(function(t){return t.category==='other'||!t.category;});
  var total=S.transactions.length;
  if(!total){
    txt.innerHTML='No data imported yet.';
    act.innerHTML='<button class="btn btn-p" onclick="showPage(\'import\')" style="font-size:13px;padding:8px 14px">↑ Import data</button>';
    bar.style.borderColor='var(--border)';
  } else if(uncat.length){
    var pct=Math.round(uncat.length/total*100);
    txt.innerHTML='<strong style="color:#f9a825">'+uncat.length+' of '+total+'</strong> transactions still uncategorised ('+pct+'%)';
    act.innerHTML='<button class="btn btn-g" onclick="startUncatReview()" style="border-color:#f9a825;color:#f9a825;font-size:13px;padding:8px 14px">Categorise →</button>';
    bar.style.borderColor='#f9a825';
  } else {
    txt.innerHTML='<span style="color:#4fc3a1">✓ All '+total+' transactions categorised</span>';
    act.innerHTML='<button class="btn btn-g" onclick="showPage(\'import\')" style="font-size:13px;padding:8px 14px">↑ Import more</button>';
    bar.style.borderColor='#4fc3a1';
  }
}

// ── INIT ──
applyTheme();
initSidebar();
loadCatDefs();
loadEntities();
loadState();
repairTransactionDates();
if(getToken()){setSyncStatus('syncing','connecting…');ghPull(false).then(function(){ghTestToken();});}else{setSyncStatus('idle','not configured');}
populateSels();showPage('overview');renderDataHealth();renderUncatBanner();updateCatStatus();
